typedef unsigned long long big_int;

class string_buf;

class stringx
{
  char* chars;
  string_buf* my_buf;
public:
  stringx();
  stringx(const stringx&);
  stringx(const char*, int = -1);
  ~stringx();
  const char* c_str() const { return chars; }
  const char* data() const { return chars; }
};

stringx operator+(const char*, const stringx&);
stringx operator+(const stringx&, const char*);

class os_developer_options
{
public:
  enum strings_t { STRING_TEXTURE_DIR = 0 };
  static os_developer_options* inst();
  const stringx& get_string(strings_t) const;
};

struct nglTexture;
void nglSetTexturePath(char*);
nglTexture* nglLoadTextureA(const char*);

enum
{
  GT_PadU,
  GT_PadD,
  GT_PadL,
  GT_PadR,
  GT_PadUL,
  GT_PadUR,
  GT_PadDL,
  GT_PadDR,
  GT_PadCircle,
  GT_PadCross,
  GT_PadTriangle,
  GT_PadSquare,
  GT_PadL1,
  GT_PadL2,
  GT_PadR1,
  GT_PadR2,
  GT_PadRelease,
  GT_PadLaunch,
  GT_PadBack,
  GT_PadStart,
  GT_ButtonSpacing
};

class Font
{
public:
  bool unset;
  char pad0[3];
  int max_width;
  char m_chars[256 * 36];
  stringx m_texname;
  unsigned int m_texwidth, m_texheight;
  nglTexture* texture;
  int numGlyphs;
  float m_ascent, m_descent;
  float m_scale;
  stringx filename;
  int m_refcount;
  nglTexture* art_button_tex[GT_ButtonSpacing];
  int art_button_width[GT_ButtonSpacing];
  int art_button_height[GT_ButtonSpacing];

  void reload();
};

void Font::reload()
{
	stringx path = "interface\\font\\"+os_developer_options::inst()->get_string(os_developer_options::STRING_TEXTURE_DIR)+"\\";
	nglSetTexturePath((char*) path.c_str());
	texture = nglLoadTextureA(filename.data());

	// load art button textures
	art_button_tex[GT_PadU] = nglLoadTextureA("igo_icon_arrow");
	for(int i=1; i<GT_PadCircle; i++)
		art_button_tex[i] = art_button_tex[0];
	art_button_tex[GT_PadCircle] = nglLoadTextureA("igo_icon_circle");
	art_button_tex[GT_PadSquare] = nglLoadTextureA("igo_icon_square");
	art_button_tex[GT_PadCross] = nglLoadTextureA("igo_icon_x");
	art_button_tex[GT_PadTriangle] = nglLoadTextureA("igo_icon_triangle");
	art_button_tex[GT_PadL1] = nglLoadTextureA("igo_icon_left_1");
	art_button_tex[GT_PadL2] = nglLoadTextureA("igo_icon_left_1");
	art_button_tex[GT_PadR1] = nglLoadTextureA("igo_icon_right_1");
	art_button_tex[GT_PadR2] = nglLoadTextureA("igo_icon_right_1");
	art_button_tex[GT_PadStart] = nglLoadTextureA("igo_icon_start");
}
